1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"os"
9		"strings"
10	
11		"github.com/gzhysuiioo/mevwatch-guard/mevwatch"
12	)
13	
14	// replicateInput 是 replicate 子命令从标准输入读取的 JSON。
15	type replicateInput struct {
16		CurrentTerm    int                      `json:"currentTerm"`
17		CommittedIndex int                      `json:"committedIndex"`
18		Log            []mevwatch.LogEntry      `json:"log"`
19		ApplyKV        bool                     `json:"applyKV"`
20		Requests       []mevwatch.AppendRequest `json:"requests"`
21	}
22	
23	// runReplicate 从标准输入读取一份 JSON（初始状态 + 顺序到达的复制请求），
24	// 把逐次接收结果与最终日志作为一份 JSON 写到标准输出。
25	// 初始状态非法或 JSON 无法解析时，以非零退出码和明确错误结束。
26	func runReplicate() int {
27		return runReplicateIO(os.Stdin, os.Stdout, os.Stderr)
28	}
29	
30	func runReplicateIO(stdin io.Reader, stdout, stderr io.Writer) int {
31		data, err := io.ReadAll(stdin)
32		if err != nil {
33			fmt.Fprintf(stderr, "replicate: read stdin: %v\n", err)
34			return 1
35		}
36		var syntaxCheck interface{}
37		if err := json.Unmarshal(data, &syntaxCheck); err != nil {
38			fmt.Fprintf(stderr, "replicate: parse input JSON: %v\n", err)
39			return 1
40		}
41		// 已识别的数值字段被显式写成 null 时，类型化解码会静默当成零值继续
42		// 处理（例如 committedIndex 为 null 被当成“尚未提交”），必须在读取
43		// 输入阶段把整份输入作为字段类型错误拒绝。检查直接扫描 JSON token
44		// 而不是先解进 map：map 解码对重复键只保留最后一次出现，既会漏掉
45		// 写在数字前面的 null，也会让后出现的 log/requests/entries 数组盖掉
46		// 前一份数组，因此重复键的每一次出现都必须单独检查。
47		if path := nullNumericFieldPath(data); path != "" {
48			fmt.Fprintf(stderr, "replicate: invalid field type: %s must be a number, got null\n", path)
49			return 1
50		}
51		var input replicateInput
52		if err := json.Unmarshal(data, &input); err != nil {
53			fmt.Fprintf(stderr, "replicate: parse input JSON: %v\n", err)
54			return 1
55		}
56		output, err := mevwatch.ReplicateWithOptions(mevwatch.InitialState{
57			CurrentTerm:    input.CurrentTerm,
58			CommittedIndex: input.CommittedIndex,
59			Log:            input.Log,
60		}, input.Requests, mevwatch.ReplicateOptions{ApplyKV: input.ApplyKV})
61		if err != nil {
62			fmt.Fprintf(stderr, "replicate: %v\n", err)
63			return 1
64		}
65		encoded, err := json.MarshalIndent(output, "", "  ")
66		if err != nil {
67			fmt.Fprintf(stderr, "replicate: encode output JSON: %v\n", err)
68			return 1
69		}
70		fmt.Fprintln(stdout, string(encoded))
71		return 0
72	}
73	
74	// nullNumericFieldPath 扫描整份输入 JSON 的 token 流，查找第一个被显式写成
75	// null 的已识别数值字段，返回它的完整位置；没有时返回空串。检查范围是初始
76	// 状态（currentTerm、committedIndex、log[i].index、log[i].term）与每条复制
77	// 请求（term、prevLogIndex、prevLogTerm、leaderCommit 及 entries[j].index、
78	// entries[j].term）；请求与条目下标从 0 开始，例如第二条请求的提交位置记为
79	// requests[1].leaderCommit。字段名识别与 encoding/json 一致，只改变字母大小
80	// 写的写法同样命中。
81	//
82	// 必须扫描 token 而不能先解进 map[string]interface{}：map 解码遇到重复键只
83	// 保留最后一次出现的值。{"currentTerm":null,"currentTerm":1} 里先出现的
84	// null 会因此漏检；log/requests/entries 自身重复出现时，前一份数组里的数值
85	// null 也会被后一份数组盖掉。token 流保留键的每一次出现，重复字段无论 null
86	// 在数字之前还是之后、数组字段重复多少次、拼写是否只改变大小写，都逃不过
87	// 检查。数组字段本身为 null、未知键（含未知对象里的同名键）里的 null 不在
88	// 检查范围内，扫描时只按结构识别已知字段，不进入其他对象与数组。
89	func nullNumericFieldPath(data []byte) string {
90		dec := json.NewDecoder(bytes.NewReader(data))
91	
92		// 取根对象的第一个 token；输入不是对象或 JSON 非法时没有可报告的数值
93		// 字段位置，交由随后的类型化解码产出既有的解析错误。
94		tok, err := dec.Token()
95		if err != nil || tok != json.Delim('{') {
96			return ""
97		}
98		for dec.More() {
99			key, ok := decodeKey(dec)
100			if !ok {
101				return ""
102			}
103			switch {
104			case strings.EqualFold(key, "currentTerm"), strings.EqualFold(key, "committedIndex"):
105				if nullScalarPath(dec) {
106					return canonicalScalarPath(key)
107				}
108			case strings.EqualFold(key, "log"):
109				if path := scanEntryArray(dec, "log", ""); path != "" {
110					return path
111				}
112			case strings.EqualFold(key, "requests"):
113				if path := scanRequests(dec); path != "" {
114					return path
115				}
116			default:
117				skipValue(dec)
118			}
119		}
120		return ""
121	}
122	
123	// scanRequests 扫描 requests 数组的完整 token 流，包括重复出现时的每一份
124	// 数组，返回其中第一个数值 null 的完整位置。
125	func scanRequests(dec *json.Decoder) string {
126		tok, err := dec.Token()
127		if err != nil {
128			return ""
129		}
130		if tok != json.Delim('[') {
131			// requests 不是数组（如 null 或被写成对象）：数组字段本身沿用既有
132			// 处理，类型错误由随后的类型化解码按既有格式报告。这里必须把整个值
133			// 消费完——起始分隔符已经读出，若就此返回，调用方的循环会落到对象
134			// 内部，把其中的字段当成外层字段，或提前结束扫描漏掉后面真正的
135			// 数值 null。
136			if d, ok := tok.(json.Delim); ok {
137				skipRest(dec, d)
138			}
139			return ""
140		}
141		for i := 0; dec.More(); i++ {
142			tok, err := dec.Token()
143			if err != nil {
144				return ""
145			}
146			if tok != json.Delim('{') {
147				// 非对象请求元素不可能含已识别字段；若它本身是容器仍要消费完整。
148				if d, ok := tok.(json.Delim); ok {
149					skipRest(dec, d)
150				}
151				continue
152			}
153			prefix := fmt.Sprintf("requests[%d]", i)
154			for dec.More() {
155				key, ok := decodeKey(dec)
156				if !ok {
157					return ""
158				}
159				switch {
160				case strings.EqualFold(key, "term"),
161					strings.EqualFold(key, "prevLogIndex"),
162					strings.EqualFold(key, "prevLogTerm"),
163					strings.EqualFold(key, "leaderCommit"):
164					if nullScalarPath(dec) {
165						return prefix + "." + canonicalScalarPath(key)
166					}
167				case strings.EqualFold(key, "entries"):
168					if path := scanEntryArray(dec, "entries", prefix+"."); path != "" {
169						return path
170					}
171				default:
172					skipValue(dec)
173				}
174			}
175			if _, err := dec.Token(); err != nil { // 请求对象的 '}'
176				return ""
177			}
178		}
179		if _, err := dec.Token(); err != nil {
180			return ""
181		}
182		return ""
183	}
184	
185	// scanEntryArray 扫描 log 或 entries 数组的完整 token 流（数组字段重复出现
186	// 时由调用方对每一份数组分别调用），返回第一个 index/term 为 null 的条目
187	// 字段完整位置。arrayName 只用于选择下标前缀的写法：根日志为 log[i]，请求
188	// 条目为 requests[r].entries[i]（parentPrefix 已含 "requests[r]."）。
189	func scanEntryArray(dec *json.Decoder, arrayName, parentPrefix string) string {
190		tok, err := dec.Token()
191		if err != nil {
192			return ""
193		}
194		if tok != json.Delim('[') {
195			// 数组字段本身为 null 或其他类型（如被写成对象）：沿用既有处理，
196			// 类型错误由类型化解码报告。与 scanRequests 相同，必须把整个值
197			// 消费完，否则对象内部的 term/index 等字段会冒充请求自身或合法
198			// 条目的字段，其后的真实字段也会被漏检。
199			if d, ok := tok.(json.Delim); ok {
200				skipRest(dec, d)
201			}
202			return ""
203		}
204		for i := 0; dec.More(); i++ {
205			tok, err := dec.Token()
206			if err != nil {
207				return ""
208			}
209			if tok != json.Delim('{') {
210				// 非对象条目不可能含已识别字段；若它本身是容器仍要消费完整。
211				if d, ok := tok.(json.Delim); ok {
212					skipRest(dec, d)
213				}
214				continue
215			}
216			prefix := parentPrefix + arrayName + fmt.Sprintf("[%d]", i)
217			for dec.More() {
218				key, ok := decodeKey(dec)
219				if !ok {
220					return ""
221				}
222				if strings.EqualFold(key, "index") || strings.EqualFold(key, "term") {
223					if nullScalarPath(dec) {
224						return prefix + "." + canonicalEntryFieldPath(key)
225					}
226				} else {
227					skipValue(dec)
228				}
229			}
230			if _, err := dec.Token(); err != nil { // 条目对象的 '}'
231				return ""
232			}
233		}
234		if _, err := dec.Token(); err != nil {
235			return ""
236		}
237		return ""
238	}
239	
240	// decodeKey 读取并断言下一个 token 是对象键。
241	func decodeKey(dec *json.Decoder) (string, bool) {
242		tok, err := dec.Token()
243		if err != nil {
244			return "", false
245		}
246		key, ok := tok.(string)
247		return key, ok
248	}
249	
250	// nullScalarPath 消费一个已识别数值字段的值 token 流，报告该次出现是否被
251	// 显式写成 null。值为对象或数组时整体跳过（结构异常的输入留给类型化解码
252	// 报告既有错误）。
253	func nullScalarPath(dec *json.Decoder) bool {
254		tok, err := dec.Token()
255		if err != nil {
256			return false
257		}
258		if tok == nil {
259			return true
260		}
261		if d, ok := tok.(json.Delim); ok {
262			skipRest(dec, d)
263		}
264		return false
265	}
266	
267	// skipValue 读取并消费一个完整的 JSON 值（标量或容器）。
268	func skipValue(dec *json.Decoder) {
269		tok, err := dec.Token()
270		if err != nil {
271			return
272		}
273		if d, ok := tok.(json.Delim); ok {
274			skipRest(dec, d)
275		}
276	}
277	
278	// skipRest 消费一个容器剩余的 token 流，open 是已经读出的起始分隔符；
279	// 起始分隔符不是 '{' / '[' 时无需消费，直接返回。
280	func skipRest(dec *json.Decoder, open json.Delim) {
281		if open != '{' && open != '[' {
282			return
283		}
284		depth := 1
285		for depth > 0 {
286			tok, err := dec.Token()
287			if err != nil {
288				return
289			}
290			if d, ok := tok.(json.Delim); ok {
291				switch d {
292				case '{', '[':
293					depth++
294				case '}', ']':
295					depth--
296				}
297			}
298		}
299	}
300	
301	// canonicalScalarPath 把命中的根状态或请求数值字段名归一为标准字段名，错误
302	// 位置始终使用标准拼写而不是输入里的大小写变体。
303	func canonicalScalarPath(key string) string {
304		for _, name := range []string{"currentTerm", "committedIndex", "term", "prevLogIndex", "prevLogTerm", "leaderCommit"} {
305			if strings.EqualFold(key, name) {
306				return name
307			}
308		}
309		return key
310	}
311	
312	// canonicalEntryFieldPath 把条目数值字段名归一为 index/term 的标准拼写。
313	func canonicalEntryFieldPath(key string) string {
314		switch {
315		case strings.EqualFold(key, "index"):
316			return "index"
317		case strings.EqualFold(key, "term"):
318			return "term"
319		default:
320			return key
321		}
322	}
