220			  {"term":1,"prevLogIndex":0,"prevLogIndex":0,"prevLogTerm":0,"leaderCommit":0,"entries":[]}]}`
221			out, _ := runReplicateRaw(t, input)
222			if !out.Results[0].Accepted {
223				t.Fatalf("duplicated legal zero must keep its ordinary meaning: %+v", out.Results[0])
224			}
225		})
226	}
227	
228	// 带重复键的合法输入在开启 applyKV 时依旧完整跑通：输出可解码，复制与键值
229	// 应用的既有行为不因扫描检查改变。
230	func TestCLIDuplicateKeysValidWithApplyKV(t *testing.T) {
231		input := `{"currentTerm":1,"currentTerm":1,"applyKV":true,"requests":[
232		  {"term":1,"prevLogIndex":0,"prevLogTerm":0,"leaderCommit":1,
233		   "entries":[{"index":1,"term":1,"command":"set k=v"}]}
234		]}`
235		var stdout, stderr bytes.Buffer
236		if code := runReplicateIO(strings.NewReader(input), &stdout, &stderr); code != 0 {
237			t.Fatalf("exit code = %d, stderr=%s", code, stderr.String())
238		}
239		var out map[string]interface{}
240		if err := json.Unmarshal(stdout.Bytes(), &out); err != nil {
241			t.Fatalf("invalid output JSON: %v\n%s", err, stdout.String())
242		}
243		kv, ok := out["finalKV"].(map[string]interface{})
244		if !ok || kv["k"] != "v" {
245			t.Fatalf("finalKV = %v, want k=v applied as before", out["finalKV"])
246		}
247	}
