		tok, err := dec.Token()
		if err != nil {
			return ""
		}
		if tok != json.Delim('{') {
			// 非对象条目不可能含已识别字段；若它本身是容器仍要消费完整。
			if d, ok := tok.(json.Delim); ok {
				skipRest(dec, d)
			}
			continue
		}
		prefix := parentPrefix + arrayName + fmt.Sprintf("[%d]", i)
		for dec.More() {
			key, ok := decodeKey(dec)
			if !ok {
				return ""
			}
